export function getNextBid(current) {
  if (current < 1.0) return +(current + 0.05).toFixed(2);
  if (current < 2.0) return +(current + 0.10).toFixed(2);
  if (current < 5.0) return +(current + 0.20).toFixed(2);
  return +(current + 0.50).toFixed(2);
}

export function formatPurse(cr) {
  if (cr == null || isNaN(cr)) return "₹2.00 Cr";
  if (cr < 1.0) return "₹" + Math.round(cr * 100) + " L";
  return "₹" + (+cr).toFixed(2) + " Cr";
}

export function calculatePurse(retentions) {
  const total = retentions.reduce((s, r) => s + r.price, 0);
  return +(120.0 - total).toFixed(2);
}
